import re as _re
def _smart(s):
    s = _re.sub(r'(^|[\s(\[—])"', '\\1“', s); s = s.replace('"', '”')
    s = _re.sub(r"(^|[\s(\[—“])'", "\\1‘", s); s = s.replace("'", "’")
